    arguments: params.arguments,
    expectedStateVersion: binding.expectedStateVersion,
    preconditions: [],
    deadline: isoDeadline(nowMs, binding.proposalTimeoutMs),
    priority: 50,
    safetyClass: params.safetyClass,
